import { test, expect } from '@playwright/test';

test.describe('Notification Dismissal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should dismiss a notification by clicking the close button', async ({ page }) => {
    // Trigger a notification to appear
    await page.getByRole('button', { name: /show notification/i }).click();

    // Verify the notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Click the close button to dismiss the notification
    const closeButton = page.getByRole('button', { name: /close/i }).first();
    await closeButton.click();

    // Verify the notification is no longer visible
    await expect(notification).not.toBeVisible();
  });

  test('should dismiss multiple notifications individually', async ({ page }) => {
    // Trigger multiple notifications
    await page.getByRole('button', { name: /show notification/i }).click();
    await page.getByRole('button', { name: /show notification/i }).click();

    // Verify both notifications are visible
    const notifications = page.getByRole('alert');
    await expect(notifications).toHaveCount(2);

    // Dismiss the first notification
    const closeButtons = page.getByRole('button', { name: /close/i });
    await closeButtons.first().click();

    // Verify only one notification remains
    await expect(notifications).toHaveCount(1);

    // Dismiss the second notification
    await closeButtons.first().click();

    // Verify no notifications remain
    await expect(notifications).toHaveCount(0);
  });

  test('should dismiss notification with keyboard interaction', async ({ page }) => {
    // Trigger a notification
    await page.getByRole('button', { name: /show notification/i }).click();

    // Verify the notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Focus on the close button and press Enter
    const closeButton = page.getByRole('button', { name: /close/i }).first();
    await closeButton.focus();
    await page.keyboard.press('Enter');

    // Verify the notification is dismissed
    await expect(notification).not.toBeVisible();
  });

  test('should verify close button is accessible and properly labeled', async ({ page }) => {
    // Trigger a notification
    await page.getByRole('button', { name: /show notification/i }).click();

    // Verify the close button exists and is accessible
    const closeButton = page.getByRole('button', { name: /close/i }).first();
    await expect(closeButton).toBeVisible();
    await expect(closeButton).toBeEnabled();

    // Verify the close button has proper ARIA attributes
    await expect(closeButton).toHaveAttribute('aria-label', /close/i);
  });
});
